{"version":3,"sources":["../scss/helpPage.scss","helpPage.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAIA;EACE,6BAAA;EACA,iBAAA;ACHF;ADIE;EENE,uCAAA;EACA,gBFMoC;EELpC,kBAAA;EACA,YCHW;EDIX,eFG8B;ACElC;ADCE;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACCJ;ADEE;EACE,kBAAA;ACAJ","file":"helpPage.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n\n.help {\n  border-top: 1px solid $gray;\n  padding-top: 15px;\n  & p,li {\n    @include fonts($defaultColor, 15px, 400)\n  }\n\n  ul, ol {\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n  }\n\n  li {\n    padding-left: 10px;\n  }\n}",".help {\n  border-top: 1px solid #D4D4D4;\n  padding-top: 15px;\n}\n.help p, .help li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 15px;\n}\n.help ul, .help ol {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.help li {\n  padding-left: 10px;\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}